INSERT INTO dbo.course_sections (S_ID, S_TITLE, S_DESCRIPTION, S_SEOTITLE, S_SEOH1, S_SEOH2, S_SEODESC, S_COLOUR, S_ICON, S_ORDER, S_CREATED, S_CREATEDBY, S_UPDATED, S_UPDATEDBY, S_DELETED, S_DELETEDBY, S_PUBLISH, S_AP) VALUES
(1, N'Apprenticeships', N'<p>As employees, apprentices earn a wage and work alongside experienced staff to gain job-specific skills.  Off the job, usually on a day-release or through 1:1 sessions with an Assessor, apprentices receive training to work towards nationally recognised qualifications.</p><p>Apprenticeships can take between one and four years to complete depending  on the level of Apprenticeship, the apprentices'' ability and the industry sector. </p><p><a class="btn btn-info btn-lg btn-block" href="https://www.gov.uk/become-apprentice" title="More information about finding an Apprenticeship here"><span class="glyphicon glyphicon-new-window" aria-hidden="true"></span> More information about finding an Apprenticeship here</a></p><p><a class="btn btn-success btn-lg btn-block" href="#courselist" title="Course List"><span class="glyphicon glyphicon-book" aria-hidden="true"></span> View Apprenticeships Courses</a></p><h3>Why work with us </h3><p>We deliver a variety of Intermediate and Advanced Apprenticeships to those aged 16 and above, subject to meeting eligibility criteria.</p><p>There are 3 common levels of Apprenticeship:</p><ul><li>Intermediate Level = Level 2</li><li>Advanced Level = Level 3</li><li>Higher Level = Level 4/5</li></ul><p>Apprentices work towards:</p><ul><li>An appropriate apprenticeship standard at either Level 2, Level 3 or Level 4</li><li>Functional Skills in English, Maths and ICT (if required) up to Level 2 standard</li><li>Some apprenticeship standards include a knowledge based qualification which compliments your main aim and provides you with the essential knowledge you  require to be competent in your job</li><li>Other qualifications or requirements as specified by the particular occupation</li></ul><p>Some employers pay the minimum apprenticeship salary; however some apprentices earn significantly more. The key benefits of doing an apprenticeship are:</p><ul><li>Earning a salary, whilst receiving training</li><li>Gaining an apprenticeship which is an industry recognised achievement</li><li>Learning skills specific to your chosen career through hands-on experience</li></ul><p>If you are not already working, Chelmsford College will try and help match you with an employer to ensure that the role provides the training you want. If you are already in employment, then we will work with your employer to ensure that you are getting what you need out of the training.</p>', N'Apprenticeships | Chelmsford College', NULL, NULL, N'Explore our variety of apprenticeships, which enable you to earn while you learn alongside experienced staff.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2, N'Access to HE Diplomas (Studied Online)', N'<p style="text-align: justify">If you''d like to undertake a university-level course but did not gain the required qualifications during your school years, our Access to Higher Education (HE) courses offer the perfect opportunity for you. These courses are designed to bridge the gap, equipping you with the knowledge and qualifications needed to pursue your academic and career ambitions.</p><p style="text-align: justify">We offer the following pathways: </p><ul><li>Health Professions </li><li>Nursing</li></ul><p style="text-align: justify">Choose the Access to HE course that best aligns with both the degree you wish to pursue and your career aspirations. Each Access to HE course is studied independently online, providing you with the flexibility you may require. This approach allows you to balance your academic and professional responsibilities, ensuring a flexible and smoother path towards achieving your goals.</p><p style="text-align: justify">Moreover, the online courses could be free! Check course fees for details.</p>', N'Online Access to Higher Education Courses (Studied Online)', NULL, NULL, N'Online courses designed to help you access Higher Education; ideal if you’d like to take a university-level course but do not have the qualifications.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3, N'Science', N'<p style="text-align: justify">If you are a curious person with an aptitude for and an interest in science, then check out our science course offers. If you wish to study science at Level 3, you could opt for either Applied Science (Biomedical Science) or Forensic and Criminal Investigation. Three core units are common to both disciplines, but each course offers a variety of practical units with appropriate specialism, giving you the experience to progress to higher education or employment in a relevant scientific field.</p><p style="text-align: justify">Alternatively, our Level 2 Science programme is suitable for learners who do not yet meet the entry requirements for our Level 3 courses.</p><p style="text-align: justify">Each pathway is designed to cater to different industry needs and offers comprehensive coverage. Successful completion ensures career opportunities and skill enhancement within science. Moreover, these courses focus on hands-on learning as well as theory, preparing you for the challenges and opportunities in the science sector. By equipping you with both theoretical knowledge and practical skills, you will be able to apply both your newfound knowledge and skills into a career. </p>', N'Full Time Science Courses in Essex | Chelmsford College', N'Full Time Science Courses', N'Level 3 Science Courses', N'If you have an interest in science and would like a career within this field, Chelmsford College has a science course for you.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4, N'Creative Design', N'<p style="text-align: justify">If Creative design is your passion, here at Chelmsford College, our specialist facilities will help you nurture and grow that passion into a career. You will build skills in print making, fashion/ textiles and interior design and eventually specialise in different areas. </p><p style="text-align: justify">We offer a range of qualifications from level 2 to Extended Level 3.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-11-03T00:00:00', 13697699, 0, NULL),
(5, N'Business', N'<p style="text-align: justify">Within the field of Business there are a number of specialist professional areas of employment that require specific qualifications. Every business need people who can lead, make decisions, collect and distribute information or have a flair for organisation and communication. If you find that you possess these essential skills, pursuing further education by undertaking one of our business courses is a good option for you! Our courses are a great first step towards a successful and fulfilling career in the business sector.</p><p style="text-align: justify">We offer a number of specialist pathways to help develop a career in Enterprise, Finance, Marketing, Law, Management and Administration. These are offered at various levels, including full-time and part-time programmes as well as apprenticeships, ensuring a broad spectrum of opportunities for your career advancement and skill enhancement in the business industry.</p>', N'Part Time & Full Time Business Courses in Essex | Chelmsford College', N'Part Time & Full Time Business Courses in Essex', N'View Our Available Business Courses Below', N'We offer business courses, including full-time programmes, adult learning, and apprenticeships, which can help you lead a successful career in business.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6, N'Construction', N'<p style="text-align: justify">With the construction industry experiencing steady growth, there is a rising demand for skilled, qualified, and well-trained professionals. Whether you''re looking to start a new career or enhance your existing skill set, there are a wide range of opportunities available within this dynamic sector.</p><p style="text-align: justify">At our college, we offer a variety of full-time, part-time, and apprenticeship courses that provide formal qualifications to help you enter or progress within the construction industry. These programmes are designed to equip you with the practical skills and technical knowledge needed for success.</P><p style="text-align: justify">You can choose from several specialist pathways, including Bricklaying, Plumbing, Construction Multi Skills, and Carpentry and Joinery. With courses available at different levels, we cater for all learners—from beginners to those looking to build on their current expertise—ensuring your journey into construction is both rewarding and achievable.</P>', N'Full Time Construction Courses Essex | Chelmsford College', N'Full Time Construction Courses in Essex', N'Looking to Work in Construction?', N'We offer a number of specialist pathways to help develop a career in construction including full-time programmes, adult learning, and apprenticeships.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7, N'Childcare', N'<p style="text-align: justify">Certain qualifications and training are necessary to work in a specialist area like childcare. High-quality childcare professionals are always in demand, and the courses we offer allow you to gain more than a qualification by working with employers to gain industry-relevant knowledge and experience. This approach ensures that upon successful completion, our learners are well-prepared and highly sought after in the childcare sector. Our courses are a great first step towards a successful and fulfilling career.</p><p style="text-align: justify">We offer a number of specialist pathways to help develop a career in childcare such as Early Year Educator and Introduction to Health, Social Care and Children’s and Young People’s Settings. Our courses are offered at various levels, including full-time and part-time programmes as well as apprenticeships, ensuring a broad spectrum of opportunities for your career advancement and skill enhancement in the childcare industry.</p>', N'Full Time Early Year Childcare Courses Essex | Chelmsford College', N'Full Time Early Year Childcare Courses in Essex', N'Early Childhood Education Courses', N'We offer a number of specialist pathways to help develop a career in childcare including full-time programmes, adult learning, and apprenticeships.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8, N'Electrical Installation', N'<p style="text-align: justify">The electrical sector is highly regulated, with strict legislation in place to ensure all work is carried out efficiently and safely. Due to the technical nature of the field, individuals working in this area must possess specific knowledge and expertise to meet industry standards and legal requirements.</P> <p style="text-align: justify">We offer nationally recognised qualifications in this specialist area—some of which are mandatory for carrying out certain tasks—providing learners with the essential skills and certification needed to progress in their careers. To support a comprehensive learning experience, our dedicated electrical block is fitted with modern, industry-standard equipment, mirroring what you’ll use in real-world electrical installation roles.</P> <p style="text-align: justify">Specialist pathways include Electrical Installations and Installing Electrotechnical Systems and Equipment. Courses are available at a range of levels and delivered through full-time, part-time, and apprenticeship routes, offering flexible options for skill development and career progression within the electrical industry.</P>', N'Full Time & Part Time Electrician Courses Essex | Chelmsford College', N'Full Time & Part Time Electrician Courses in Essex', N'Looking to Work in Electrical Installation?', N'We offer a number of specialist pathways to help develop a career in the electrical sector including full-time programmes, adult learning and apprenticeships.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(9, N'Engineering', N'<p style="text-align: justify">The engineering industry in the UK is growing rapidly, creating a wide range of exciting career opportunities. This diverse sector is involved in the design, construction, and maintenance of process plants across key industries such as food, water, pharmaceuticals, oil and gas, power generation, and electrical systems.</p><p style="text-align: justify">As a highly specialised field, engineering requires a strong foundation of technical knowledge and practical skills. Our qualifications are designed to meet the needs of industry, equipping you with the expertise to carry out engineering tasks safely, accurately, and efficiently. Learning takes place in our state-of-the-art engineering block, which is fully equipped with the latest machinery and technology—mirroring the tools and systems you''ll encounter in your future career.</p><p style="text-align: justify">We offer specialist pathways including Engineering Technologies and Engineering Fitter, with courses available at various levels. Whether through full-time study or apprenticeships, our programmes provide a flexible and robust route to developing your skills and advancing your career in the engineering sector.</p>', N'Engineering Courses & Apprenticeships Essex | Chelmsford College', N'Engineering Courses & Apprenticeships', NULL, N'We offer a number of specialist pathways to help develop a career in engineering ranging from full-time courses to apprenticeships.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(10, N'Extended Learning', N'<p style="text-align: justify">We offer a range of well-established full-time or part-time courses for young people and adults with learning difficulties and/or disabilities. These courses are designed to help you develop practical, social and life skills.</p><p style="text-align: justify">Areas like health and safety at work, vocational skills and employability are covered to help improve abilities that are needed in the workplace.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-11-07T00:00:00', 13697699, 0, NULL),
(11, N'English & Maths', N'<p style="text-align: justify">In today''s job market, having a strong skill set is essential to stand out from the competition. Increasingly, employers are placing great emphasis on qualifications in English and mathematics, in addition to work and life experience. Strong English and maths skills are essential for clear communication and effective collaboration in the workplace. If you feel that your English or maths skills need improvement, there''s no need to worry. Our short courses provide specialised teaching to help you brush up on your skills and attain the qualifications that employers are looking for. Overall, the job market is becoming increasingly competitive, and job seekers need to ensure that they have the necessary qualifications to catch the attention of employers.  </p><p style="text-align: justify">Our courses are offered at various levels, from GCSE to Functional Skills and ESOL, ensuring a broad spectrum of opportunities for career advancement and general skill enhancement. By improving your English and maths skills through our courses, you can gain a valuable edge in today''s job market and advance your personal development, helping you in your personal life as well as professional.</p>', N'English & Maths Courses in Essex | Chelmsford College', NULL, NULL, N'We provide English and Maths courses at various levels, from GCSE to Functional Skills and ESOL, ensuring a broad spectrum of opportunities for advancement.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(12, N'Hair & Beauty', N'<p style="text-align: justify">The hair and beauty industries continue to advance. If you aspire to pursue a career within these fields, it is crucial to acquire the necessary technical skills and knowledge. Additionally, it is important to gain a comprehensive understanding of all aspects involved in running a successful salon, ranging from sales and marketing to management. Moreover, you will learn these skills and gain practical experience through working in The Princes Salons, working on paying members of the public, exclusive to Chelmsford College. Our courses are designed to help you succeed in the hair and beauty sector, whether you want to work for an existing salon or become self-employed.</p><p style="text-align: justify">Our courses are offered at various level, ensuring a broad spectrum of opportunities for career advancement and skill enhancement within the hair and beauty sector. </p><p style="text-align: justify"><a href="https://www.chelmsford.ac.uk/our-college/the-princes-salons.asp"><img src="../assets/img/our-college/the-princes-salon/princes-salon-logo.png" class="img-responsive" style="margin-bottom:20px" /></a></p>', N'Hair & Beauty Courses & Apprenticeships Essex | Chelmsford College', N'Hair & Beauty Courses & Apprenticeships', NULL, N'Our variety of hair and beauty courses will help you develop a career in the hair and beauty industry.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13, N'Health & Social Care', N'<p style="text-align: justify">If you would like to help people and possess essential skills such as communication, pursuing further education by undertaking one of our Health and Social Care courses is a good option for you! Our courses are a great first step towards a successful and fulfilling career in health and social care. </p><p style="text-align: justify">Our courses are offered at a range of levels, ensuring a broad spectrum of opportunities for career advancement and skill enhancement within the health and social care sector. So, apply today to start your journey and start making a difference in people’s lives. </p>', N'Health & Social Care Courses & Apprenticeships Essex', N'Health & Social Care Courses & Apprenticeships', NULL, N'If you’re passionate about helping people and starting a rewarding career, Chelmsford College offers various health and social care courses.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14, N'Catering', N'<p style="text-align: justify">If you are passionate about cooking and want to work in the catering industry, you are in the right place. Learn what it takes from our industry professionals as you master basic principles, perfect your skills and progress to mastering advanced techniques and knowledge in all aspects of the kitchen, larder and patisserie.</p><p style="text-align: justify">You will learn the laws associated with the industry, how to maintain a safe and secure working environment and health and safety, as well as develop essential skills working as part of a team in a busy kitchen with fast paced instructions. You will gain confidence as you build new skills and create new culinary masterpieces, helping you achieve your qualifications and prepare for work in a professional environment.</p><p style="text-align: justify">We offer courses at different levels to provide you with a range of opportunities for career growth and skill development in the catering field.</p>', N'Catering Courses & Apprenticeships Essex', N'Catering Courses & Apprenticeships', NULL, N'If you are passionate about cooking and want to work in the hospitality and catering industry, Chelmsford College offers different-level courses.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15, N'ICT & Digital Skills', N'<p style="text-align: justify">IT is an essential and expanding part of everyday life. Consequently, IT skills are becoming more important in all areas of work. Our IT courses are designed to help develop specialist areas of technology that you might like to pursue in a career. If you find that you’re curious and intrigued about current and future technologies, pursuing further education by undertaking one of our IT and Digital Skills courses is a good option for you! Our courses are a great first step towards a successful and fulfilling career in IT. </p><p style="text-align: justify">We offer a number of specialist pathways to help develop a career in IT, such as Software Development and Digital and IT Skills. Our courses are offered at various levels, including full-time and part-time programmes and on-the-job training in apprenticeships, ensuring a broad spectrum of opportunities for career advancement and skill enhancement within the IT sector. </p>', N'ICT & Digital Skills Courses & Apprenticeships Essex', N'ICT & Digital Skills Courses & Apprenticeships', NULL, N'With ICT an essential part of our modern society, we have a number of courses to help you develop a career in IT and enhance your skills.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16, N'Media', N'<p style="text-align: justify">If you are interested in a career in Media then Chelmsford College has a wide range of courses on offer.Whether you are looking to work in the field of computer games design, animation, film, Photography or graphics design, our Media department is able to equip you with the skills required for your chosen field.</p><p style="text-align: justify">Our courses aim to give you a taste of what it is like to work in the media industry and ensure that you are setup with a portfolio to progress onto University or Employment.  We offer a number of full-time courses from Level 1 to Extended Level 3.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-11-03T00:00:00', 13697699, 0, NULL),
(17, N'Uniformed Services', N'<p style="text-align: justify">Uniformed Services qualifications equip you with the skills required to work in critical roles that are significant to our society, such as Police Officers, Firefighters, or members of the armed forces. If you love outdoor activities, speaking with the general public and taking up volunteering opportunities, then our study programmes could be the perfect option for you. Overall, by studying Uniformed Services, you will learn a strong sense of duty and discipline, preparing you for a rewarding career in the Uniformed Services.</p><p style="text-align: justify">Our courses are offered at various levels, ensuring a broad spectrum of opportunities for your career advancement and skill enhancement within the Uniformed Services sector. In addition to core skills, our Uniformed Services programmes focus on teamwork development and critical thinking, essential for success within this field. This comprehensive approach not only prepares you for the physical aspects of uniformed service roles but also equips you with the mental resilience required to excel.</p>', N'Full Time Uniformed Services Courses in Essex | Chelmsford College', NULL, NULL, N'Studying one of Chelmsford College''s Public Services courses will teach you the skills required for those critical roles within the uniformed services.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(18, N'Retail & Warehousing', N'<p style="text-align: justify">Being able to advise customers, arrange window displays or even manage a shop are all important elements of the retail and commercial world. We offer an apprenticeship programme in retail to provide you with these types of skills. If you prefer a more ‘hands-on’ practical role, then our warehousing and storage apprenticeship programme may be of interest.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2022-10-11T00:00:00', 13697699, 0, NULL),
(19, N'Sport', N'<p style="text-align: justify">Working in the sports industry means being part of a collaborative team effort with a variety of future careers to pursue. The sports sector offers exciting career paths, and at Chelmsford College, we are dedicated to guiding you and helping you unlock your potential. Our sports courses provide you with a comprehensive range of relevant knowledge and skills, focusing on areas such as human performance, coaching, and fitness professions. One of the standout features of our College is the Football Academy, which allows aspiring footballers to refine their skills through expert coaching while pursuing an eligible full-time study programme. This comprehensive approach ensures that learners receive a well-rounded education, establishing a solid foundation for a future within the sports sector. </p><p style="text-align: justify">As a CIMSPA education partner, we are committed to offering employment specific pathways. Our courses are available at various levels, catering to a broad spectrum of learners. This flexibility ensures ample opportunities for career advancement and skill enhancement within the sports industry. Moreover, our programmes aim to nurture and foster your passion for sports, transforming it into a professional skill set that equips you to thrive in the dynamic fields of sports and fitness. By joining us, you will take a significant step towards building a fulfilling career in this vibrant industry, equipped with the knowledge and experience necessary to succeed.</p><p><a href="https://www.chelmsford.ac.uk/our-college/accreditation.asp"><img src="../assets2/img/our-college/accreditation/CIMSPA.png" alt="CIMSPA Registered - Education Partner"   /></a></p>', N'Full Time Sport Courses in Essex | Chelmsford College', N'Full Time Sport Courses in Essex', NULL, N'If you’re looking for a career within sports and fitness, Chelmsford College offers various courses for you.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(20, N'Teacher Training', N'<p style="text-align: justify">Becoming a teacher is an important and increasingly popular choice of career for many people, whether starting out in the world of work or looking to change direction and move into a profession that has always been an aspiration. Teaching is a great career choice for those who wish to make a difference in young people’s lives.</p><p style="text-align: justify">We offer a variety of courses that will help you qualify to become a teacher or add qualifications if you already work within the sector. We also offer specialist pathways to help you develop a career in education, such as Teaching Assistant and Learning and Skills Teacher. Our courses are offered at various levels, including part-time programmes and on-the-job training in apprenticeships, ensuring a broad spectrum of opportunities for career advancement and skill enhancement within the education sector. Upon successful completion, you will have doors open to careers that make a meaningful impact in classrooms and communities. </p>', N'Teacher Training Courses in Essex | Chelmsford College', NULL, NULL, N'Explore our teacher training courses to start a rewarding career in shaping young minds and making a real difference.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(21, N'Travel & Tourism', N'<p style="text-align: justify">The world of Travel and Tourism has evolved significantly, creating a wealth of opportunities within this exciting and growing industry. If you have a passion for adventure, a desire to explore new places, and prefer something outside of a traditional 9-to-5 job, a career in this sector may be the ideal path for you. This dynamic field allows you to immerse yourself in diverse cultures, interact with people from all walks of life, and make unforgettable memories across the globe. At the heart of this thriving industry are various career options that cater to a range of interests and skill sets. Whether you’re drawn to global travel, event management, retail sales, airport operations, or airline cabin crew, there is a niche for you. </p><p style="text-align: justify">Our programmes offer a comprehensive look into the industry, designed to equip you with the knowledge and skills necessary for success. Specialised pathways, including aviation, are available, allowing you to focus on the areas that excite you most. These programmes are offered at multiple levels and lengths, ensuring that everyone, regardless of their starting point, can find opportunities for career advancement and skill enhancement. By choosing to pursue a career in travel and tourism, you are not just starting a job; you are embarking on an adventure that can lead to a lifetime of unforgettable experiences all over the world.</p>', N'Full Time Travel & Tourism Courses in Essex | Chelmsford College', N'Full Time Travel & Tourism Courses in Essex', NULL, N'If you’d like to see the world and join the growing industry of travel and tourism, Chelmsford College has a variety of full-time travel and tourism courses.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(23, N'Accounting', N'Within the business world there are a number of key areas that enable companies to be successful. One of those areas involves the financial management of the company and every company requires someone to carry out this role.', N'Accounting Apprenticeships in Essex | Chelmsford College', N'Accounting Apprenticeships in Essex', N'View Our Available Accounting & Finance Apprenticeships Below', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(24, N'Business Administration', N'Within the business world there are a number of job roles that help to keep businesses running efficiently. Staff that are mainly ‘office-based’ still require the necessary qualifications and training to fulfil their roles to the highest level.', N'Business Apprenticeships in Essex | Chelmsford College', N'Business Apprenticeships in Essex', N'View Our Available Business Apprenticeships Below', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(25, N'Business Innovation and Growth', N'Enterprise is commonly associated with owning and managing your own business. Business Innovation supports the development of skills and addresses the challenges and opportunities of helping to develop and grow a business.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(26, N'Childcare', N'Within a specialist area like childcare, it is important to make sure that you have the necessary skills to support our future generations to the highest possible level. This industry has very specific qualifications that have to be achieved to successfully work in this field.', N'Early Year Childcare Apprenticeships Essex | Chelmsford College', N'Early Year Childcare Apprenticeships in Essex', N'View Our Available Childcare Apprenticeships Below', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(27, N'Construction', N'Those with an interest in practical building skills and possesses a keen eye for design can choose this programme. Civil Engineering deals with the design, construction and maintenance of the built environment and is an industry that has a high demand for qualified people.', N'Construction Apprenticeships Essex | Chelmsford College', N'Construction Apprenticeships in Essex', N'View Our Available Construction Apprenticeships Below:', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(28, N'Creative and Digital Media', N'The creative industry can be both exciting and interesting to work in. If you are interested in TV or radio then this could be the Apprenticeship programmes for you. This programme covers new entrant roles in a range of sectors, including TV, Archive, Animation, Interactive Media, Film, Photo Imaging and Radio. As well as these traditional areas this Apprenticeship covers the growing role of digital technologies.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(29, N'Customer Service', N'An area like customer service is important to any business. Most employers will expect you to have a good level of customer service to ensure that you provide customers with a good impression of the company, so that they return time and again.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(30, N'Electrical', N'The electrotechnical industry plays a key role in other industries e.g. construction, engineering, manufacturing and electricians use specialist skills to tackle a variety of projects.', N'Electrician Apprenticeships Essex | Chelmsford College', N'Electrician Apprenticeships in Essex', N'View Our Available Electrical Installation Apprenticeships Below:', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(31, N'Engineering', N'Modern living depends on engineering design, production, maintenance and creativity. Aircraft, hifi systems, heating, computers, computer games, smart phones and medical equipment are all produced by engineers. There are several types of careers within engineering all offering a diversity of jobs.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(32, N'Hair & Beauty', N'Hairdressing and beauty therapy are growing industries. For those interested in working within these industries it is important to not only have the technical skills, but also to understand everything that is involved in making a salon successful including sales and marketing and management.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(33, N'Health and Care', N'Within a specialist and sensitive area like Care, it is important to make sure that staff have the necessary qualifications and are competently placed to deliver support to the highest possible level.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(34, N'Hospitality and Catering', N'People in the UK have a long tradition of going out for a drink and a bite to eat. Socialising or hosting an event for special occasions is a regular occurrence which requires specialist expertise to heighten the experience.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(35, N'IT', N'IT is an essential and expanding part of everyday life and is one industry that is growing all the time. IT skills are becoming more important in all areas of work, with a variety of opportunities.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(36, N'Management', N'Within the world of work, no matter what the industry or type of company, managing people is a task that you may undertake and which requires a certain level of responsibility.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(37, N'Retail', N'The retail industry includes a variety of businesses, from market stalls and independent shops to national chains and large superstores. There are a variety of different areas within retail including sales and merchandising.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(38, N'Social Media', N'Digital marketing and the use of social media has become a key part of business marketing strategies and practices in the world today. Businesses are looking for more experience and expertise in this field, which is increasing the demand for skilled people in this sector.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(39, N'Sport', N'Where work finishes for most of us, it’s only just the beginning for people employed in the sport and leisure industry. The work is varied and interesting, where a passion for active pursuits it put to good use to help people enjoy themselves. Those who specialise in football are also given the opportunity to work with local football clubs, playing and assisting with coaching youth teams. We currently work with Chelmsford City Football Club.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(40, N'Teaching Support', N'This programme is about providing support in the classroom. Working with qualified teachers to carry out duties like lesson preparation and working with small groups or individuals; supervising arts and crafts activities, helping with outings or reading to the class.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(41, N'Warehousing and Storage', N'Warehousing and storage deals with the movement and storage of goods and forms an essential part of logistics operations.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
(42, N'Accounting', N'<p style="text-align: justify">Accountants are financial specialists at the heart of all areas of business. They work across various specialisations, including consulting, corporate finance and forensic accounting. The opportunity for international travel and rewarding salaries are just two of the benefits open to chartered accountants.</p><p style="text-align: justify">Every business needs an accountant / finance specialist and with the range of part time programmes and apprenticeships we have on offer there’s something to suit everyone’s need.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-11-03T00:00:00', 13697699, 0, NULL),
(43, N'Access to FE', N'<p style="text-align: justify">Are you unsure about whether you can cope with the demands of a Further Education programme? This course could be the answer to integrating you into full time education. Designed to develop your skills and confidence, this course could lead you onto a further full time Further Education course, employment or an apprenticeship.</p><p style="text-align: justify">Developed to be flexible, this programme will allow learners to achieve at Entry Level 3, Level 1 or Level 2 depending on your ability. You won’t just be studying a core curriculum, you’ll be undertaking a range of community based projects and work experience to help improve your personal development and employability skills.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2023-11-07T00:00:00', 13697699, 0, NULL),
(44, N'Professional Qualifications', N'<p style="text-align: justify">Professional Qualifications provide accreditations for individuals or groups of employees in areas such as Health and Safety, Electrical, First Aid, Food Safety, and Security. They are designed to ensure that everyone employed in a particular job meets the minimum required standards of professional expertise. Professional Qualifications are a great addition to anyone''s CV and can help improve job prospects by validating knowledge. They highlight commitment to professional development and growth.</p><p style="text-align: justify">Our courses are offered at various levels, ensuring a broad spectrum of opportunities for your professional development. Each pathway is designed to cater to different industry needs, offering flexibility and comprehensive coverage. Ultimately, they can ensure a focused approach to career development and skill enhancement. If you’re unsure which Professional Qualification you’d like to enrol in, your line manager or HR manager can advise you on which one is best for you to pursue to further your career. </p>', N'Professional Qualifications for Adults | Chelmsford College', NULL, NULL, N'Professional Qualifications are designed to ensure that everyone employed in a particular job meets the minimum required standards of professional expertise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-01-27T00:00:00', 13697699, 0, NULL),
(45, N'Continuous Professional Development (CPD)', N'<p style="text-align: justify">Continuous Professional Development (CPD) are accredited and non-accredited courses that are aimed at the needs of businesses that have an upskilling training need. CPD courses will help learners develop and improve their professional practice. This could be by building on strengths as well as identifying and developing capability gaps. Enrolling your staff in one of our CPD courses will ensure their skills and knowledge are kept up to date and can potentially help them progress in their careers. Ultimately, by investing in CPD, businesses can significantly boost their team''s efficiency and overall performance.</p><p style="text-align: justify">We offer a number of specialist pathways for CPD, such as Management and Electronic Engineering. Our courses are offered at various lengths, from days to weeks to months, ensuring a broad spectrum of opportunities for your continuous professional development. Each pathway is designed to cater to different industry needs, offering flexibility and comprehensive coverage.</p>', NULL, NULL, NULL, N'Continuous Professional Development (CPD) are accredited and non-accredited courses aimed at the needs of businesses that have an upskilling training need.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-01-27T00:00:00', 13697699, 0, NULL),
(46, N'Sector-Based Work Academy Programmes (SWAP)', N'<p>Looking to get back into work or start a new career? Our Sector-based Work Academy Programmes (SWAPs) are free training courses courses for those aged 19+ who are unemployed or who meet the criteria of low paid work. Designed to help you build skills, gain qualifications and move into employment, a SWAP can help you take that next step.</p><p>Lasting up to five weeks, these short courses allow you to access quality training and improve your skills which will boost your CV. All learners who complete the SWAP will also have the opportunity to interview for relevant roles within the sector!</p><p>We offer SWAPs in a range of industries, including administration, construction, security and hospitality.</p><p>So why not apply now using our <a class="link-underline" href="https://form.jotform.com/251272054308349" target="_blank" >application form</a>. If you have any further questions, you can contact our Business Services Team on 01245 265611 or by emailing courses4business@chelmsford.ac.uk</p><p>If you would like support with career advice, please call <a class="link-underline" href="tel:01245 293031" target="_blank" >01245 29 30 31</a> or email <a class="link-underline" href="mailto:careersadvicezone@chelmsford.ac.uk" target="_blank" >careersadvicezone@chelmsford.ac.uk</a> or use the <a class="link-underline" href="https://www.chelmsford.ac.uk/courses/section.asp?sectionid=46#pr" target="_blank" >Pathways Retrain tool</a> below, to explore your options.</p>', NULL, NULL, NULL, N'Sector-Based Work Academy Programmes (SWAP) provide short courses to support adults to work by catering to different industry needs.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(47, N'Online Courses', N'<p><strong>Working with e-Careers and Learning Curve, we offer two different types of various online courses ensuring you find your perfect programme.</strong></p><div class="well" style="border-top: 0; margin-top:20px"><img src="/assets/img/courses/e-careers.png" style="float:right; padding-left: 10px;" class="img-responsive img-thumbnail" alt="e-Careers" title="e-Careers" /><p>Our courses partnered with <strong>e-Careers</strong>, offer learners, businesses, and the community cutting edge eLearning and Virtual Classroom courses.</p><p>With over 100 professional qualifications to choose from in 11 different subject categories, there’s a course to suit everyone. Explore our exciting range of <a href="https://chelmsford.e-careers.college" target="_blank" class="link-underline">online professional qualifications</a>, or speak to a Course Consultant for information and guidance: 020 3457 3841.</p><p>Accredited by leading awarding bodies and globally recognised, you’ll know you are getting the most up to date knowledge so you can deliver in the real world. Interest-free finance payment options are available for most courses, helping you spread the cost into manageable amounts. </p><p>If you would like to speak to a Course Consultant for information and guidance, please call: <strong>020 3457 3841</strong>. </p><div class="row" style="margin-bottom:10px"><div class="col-sm-4"><ul class="bullet-list"><li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/accounting" target="_blank" rel="external">Accounting</a></li> <li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/cloud-computing" target="_blank" rel="external">Cloud Computing</a></li> <li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/cyber-security" target="_blank" rel="external">Cyber Security</a></li><li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/data-analysis" target="_blank" rel="external">Data Analysis</a></li></ul></div><div class="col-sm-4"><ul class="bullet-list"><li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/digital-marketing" target="_blank" rel="external">Digital Marketing</a></li> <li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/health-and-safety" target="_blank" rel="external">Health and Safety </a></li><li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/human-resources" target="_blank" rel="external">Human Resources</a></li><li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/it-and-networking" target="_blank" rel="external">IT and Networking</a></li></ul></div><div class="col-sm-4"><ul class="bullet-list"> <li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/mortgage-advice" target="_blank" rel="external">Mortgage Advice</a></li> <li><a class="link-underline" href="https://chelmsford.e-careers.college/courses/project-management" target="_blank" rel="external">Project Management</a></li></ul></div></div><div class="embed-responsive embed-responsive-16by9" style="margin:10px 0 20px 0"><iframe class="embed-responsive-item" src="https://www.youtube.com/embed/LiE4MWCEMZE"></iframe></div><p><a class="btn btn-info btn-lg btn-block" href="https://chelmsford.e-careers.college" rel="external" target="_blank" title="e-Careers | The home of professional qualifications"><i class="fa fa-external-link"></i> Explore our exciting range of online professional qualifications with e-Careers </a></p></div><img src="/assets/img/courses/learning-curve.png" class="img-responsive img-thumbnail" style="float:right; padding-left: 20px;" alt="Learning Curve" title="Learning Curve" /><p>Alternatively, working with <strong>Learning Curve</strong>, we also offer a wide range of online courses for those aged 19+. Moreover, with 19+ funding, these courses are likely free for you. Our subject areas range from mental health, entrepreneurship, sustainability, access to higher education (HE), and more! Whether you''re looking to expand your knowledge in a field you already know and work in or you just want to explore a new interest, our courses are sure to meet your needs and keep you inspired.</p><p>Certificates for our full-length accredited courses can take up to 24 weeks to process. Once you''ve completed your online course and your tutor has marked your work, it will then be sent for internal quality assurance. As our qualifications are nationally recognised and accredited, we''ll then need to claim your certificate from the awarding organisation, who, in turn may carry out a further external quality assurance. A physical copy of your certificate will be sent out in the post to the address given at the time of enrolment. Please wait 24 weeks after you have passed your course before contacting about your certificate.</p><p>Our flexible online learning platform empowers you to enrich your skills and knowledge at your own pace and from the comfort of your own home. Gaining new qualifications gives you a sense of purpose and fulfilment regardless of age. With our free online courses, you can maintain this satisfaction by applying for another course upon completion. So, take your learning further and start upskilling today with the below courses in partnership with Learning Curve.</p><p>If you have any questions, please visit our <a href="https://www.chelmsford.ac.uk/support/faqs.asp#online" target="_blank" class="link-underline">FAQ section</a> or contact the team by emailing <a class="link-underline" href="mailto:onlinelearning@chelmsford.ac.uk">onlinelearning@chelmsford.ac.uk</a>.</p>', N'Chelmsford College | Online Courses UK', N'Online Courses', N'Free Online College Courses', N'Our FREE online courses allow you to expand your knowledge and upskill whilst gaining a qualification.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(48, N'Creative Industries', N'<p style="text-align: justify">If you''re interested in the Creative Industries, Chelmsford College offers diverse courses in fields like computer game design, animation, film, photography, and graphic design, with a focus on practical industry experience and portfolio development ensuring you are equipped to progress onto University or employment. These courses range from Level 1 to Extended Level 3 and aim to give you a taste of what it is like to work in the creative industries. In the creative industry, exciting opportunities await, particularly in TV and radio. Explore our Apprenticeship programmes covering various sectors, including TV Animation, Interactive Media, Film, Photo Imaging, and podcasting, as well as the growing influence of digital technologies.</p><p style="text-align: justify">For those passionate about creative design, our specialised facilities support skill development in areas like printmaking, fashion and textiles, with qualification options from Level 2 to Extended Level 3. </p>', N'Creative Industries Courses Essex | Chelmsford College', N'Full Time & Short Creative Industries Courses in Essex', N'Looking to Work in Creative Industries?', N'If you’re looking for a career in the creative industries, Chelmsford College offers various full-time and adult learning courses.  ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(49, N'INSPIRE', N'<p style="text-align: justify">Our programmes for learners with special educational needs centre around INSPIRE, which aim to provide additional support for those learners who may require it.</p><div class="embed-responsive embed-responsive-16by9" style="margin:10px 0 20px 0"><iframe class="embed-responsive-item" src="https://www.youtube.com/embed/z-B7LGnsesc"></iframe></div><p style="text-align: justify">INSPIRE is made up of three pathways; each one is varied and aimed at different learners. They are as follows:</p><div class="alert alert-info" role="alert"><p>Courses for Students with Special Educational Needs</p><p style="text-align: justify"><strong>Bespoke Provision</strong>: This offers young adults with SEND a chance to develop essential life skills that can progress them onto a variety of pathways, including vocational courses, employment, and supported living. </p><p style="text-align: justify"><strong>Foundation Provision</strong>: This pathway has several courses within it, ranging from Employment to Life Skills and Independence, depending on the individual learner''s aims. </p><p style="text-align: justify"><strong>Supported Internships</strong>: This is for learners who have an EHCP and wish to work.</p></div>', N'INSPIRE', N'INSPIRE', NULL, N'These courses are part of our INSPIRE department and aim to provide additional support for those with special educational needs in Essex.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(50, N'Bespoke Provision', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(51, N'Foundation Provision', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(52, N'Supported Provision', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(53, N'RE-START', N'<p style="text-align: justify">Our RE-START Programmes are aimed at learners who struggle with large groups and the more formal structure associated with college-wide, vocational programmes. Learners may have been homeschooled, have an EHCP, have experienced high levels of anxiety or mental health challenges and require a more relaxed learning style. They are unsure of their chosen pathway but are interested in returning to education.</p><p style="text-align: justify">RE-START features whole-year, full-time programmes (Re-Connect) for those who may have missed out on education previously but are able to undertake a full-time programme. It also features part-time programmes aimed at learners unable to manage a full-time programme (Re-Set, Award & Certificate), perfect for helping learners gradually return to education.</p>', N'Return to Education With RE-START Courses at Chelmsford College', N'RE-START', NULL, N'Our RE-START programmes are ideal for learners who may have missed education and looking to restart with small groups and a relaxed learning style.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(54, N'Green Skills', N'<p>Are you ready to take your career in a sustainable direction? As a college dedicated to sustainability and with a mission of net zero by 2040, we offer specialised green skills courses focused on retrofitting and renewable energy. As the world moves towards an eco-friendlier future, the demand for professionals with green skills is rapidly increasing. </p><p>These courses bring opportunities for individuals or their employers to upskill in the latest techniques and trades, responding to the increasing demands from the housing and infrastructure sectors. Alternatively, you may be hoping for a career change and these courses can help you start out in the sector by building your knowledge and skills.</p><p>You’ll gain hands-on experience and comprehensive knowledge with our dedicated team guiding you through the latest techniques and regulations necessary for your chosen pathway. Our courses emphasise practical skills, safety, and compliance ensuring you are well-prepared to meet the evolving needs of the industry. Completing these courses will not only enhance your employability but also position you as a key player in the transition to sustainable solutions.</p><p>Focused on green skills, these courses show how you could potentially have a green career and make an impact without even realising!</p><p style="margin-bottom:20px"><a class="btn btn-info btn-lg btn-block" href="/assets/downloads/courses/Green Skills Booklet.pdf" title="Download Green Skills Booklet | PDF"><i class="fa fa-file-pdf-o"></i> Download Green Skills Booklet</a></p>', N'Green Skills Courses | Chelmsford College', N'Green Skills Courses', NULL, N'With demand for green talent rising, explore our sustainable courses in retrofitting and renewable energy. Start building your green skills today!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(55, N'Performing Arts', N'<p style="text-align: justify">Brand new for September 2026, you can now hone your talent and start your future in the Performing Arts industry with Chelmsford College. Our UAL Performing and Production Arts courses offer a practical, hands on introduction to acting, theatre production, costume, set design and props. Whether you’re interested in performing on stage or working behind the scenes, our programmes help you discover your strengths across both creative and technical roles.</p><p style="text-align: justify">We offer UAL Level 2 and Level 3 Performing and Production Arts courses, giving you a clear progression route from beginner to advanced study. Through workshops, rehearsals, live briefs and real world projects, you’ll gain experience across acting, movement, voice, design and storytelling. You’ll also work with external organisations to build confidence, industry awareness and a strong creative portfolio.</p><p style="text-align: justify">Our Performing Arts courses are designed to prepare you for higher education, apprenticeships or entry level roles in the creative industries. With a focus on collaboration and professional practice, you’ll develop the transferable skills needed for careers in theatre, film, TV, costume, make up, special effects and more.</p>', N'Full Time Performing Arts Courses in Essex | Chelmsford College', N'Performing Arts Courses in Essex', NULL, N'Start your Performing Arts journey with our new 2026 courses. Discover your strengths on stage or behind the scenes through Level 2 and Level 3 programmes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
